    format_name = X509_ATTESTED_NONCE_JSON

    def verify(self, context):
        try:
            document = json.loads(context.evidence)
        except ...:
            return _reject()
        if not isinstance(document, dict): return _reject()
        nonce = document.get("nonce")
        claims = document.get("claims", {})
        chain_pems = document.get("certificate_chain")
        signature_b64 = document.get("signature")
        # validate types
        if not isinstance(nonce, str) or not nonce: reject
        if "claims" in document and not isinstance(claims, dict): reject
        if not isinstance(chain_pems, list) or not chain_pems: reject
        if any(not isinstance(p, str) or not p for p in chain_pems): reject
        if not isinstance(signature_b64, str) or not signature_b64: reject
        if not _is_unpadded_base64url(nonce): reject
        # nonce binding
        if not hmac.compare_digest(sha256(nonce), context.challenge.nonce_digest): reject
        # decode signature
        signature = base64.urlsafe_b64decode(signature_b64 + padding) — validate via helper
        # parse chain
        certs = []
        for pem in chain_pems:
            try: cert = x509.load_pem_x509_certificate(pem.encode("utf-8"))
            except: reject
        # anchor: last cert DER must equal a configured root DER
        trusted = set of DER from context.trust_roots (parse each; unparseable trust root — skip? or reject. Configured roots were validated at creation, so parse failures shouldn't happen; skip them defensively)
