            # CA usage for non-leaf
            if i > 0:
                bc = cert.extensions.get_extension_for_class(x509.BasicConstraints) — if not found or not bc.value.ca: reject
        # signature chain: cert[i] signed by cert[i+1]
        for i in range(len(certs)-1):
            _verify_cert_signature(certs[i], certs[i+1].public_key()) -> bool
        # leaf signature over canonical JSON
        payload = canonical json
        verify with certs[0].public_key()
        return accepted
