Main verify:

```python
class X509AttestedNonceJSONVerifier(Verifier):
    format_name = X509_ATTESTED_NONCE_JSON

    def verify(self, context):
        try:
            document = json.loads(context.evidence)
        except (json.JSONDecodeError, UnicodeDecodeError):
            return _reject()
        if not isinstance(document, dict):
            return _reject()

        nonce = document.get("nonce")
        claims = document.get("claims", {})
        chain_pems = document.get("certificate_chain")
        signature_b64 = document.get("signature")
        if not isinstance(nonce, str) or not nonce:
            return _reject()
        if "claims" in document and not isinstance(claims, dict):
            return _reject()
        if (
            not isinstance(chain_pems, list)
            or not chain_pems
            or any(not isinstance(p, str) or not p for p in chain_pems)
        ):
            return _reject()
        if not isinstance(signature_b64, str) or not signature_b64:
            return _reject()
        if not _is_unpadded_base64url(nonce):
            return _reject()

        # The attested nonce must be exactly the nonce of the bound challenge.
        if not hmac.compare_digest(
            hashlib.sha256(nonce.encode("ascii")).hexdigest(),
            context.challenge.nonce_digest,
        ):
            return _reject()

        signature = _decode_unpadded_base64url(signature_b64)
        if signature is None:
            return _reject()

        certificates = []
        for pem in chain_pems:
            try:
                certificates.append(x509.load_pem_x509_certificate(pem.encode("utf-8")))
            except (ValueError, TypeError):
                return _reject()

        # The chain root must be byte-identical to a trust root configured
        # for exactly this tenant and workload.
        trusted_ders = set()
        for root_pem in context.trust_roots:
            try:
                trusted_ders.add(
                    x509.load_pem_x509_certificate(root_pem.encode("utf-8")).public_bytes(Encoding.DER)
                )
            except (ValueError, TypeError):
                continue
        if not trusted_ders:
            return _reject()
        if certificates[-1].public_bytes(Encoding.DER) not in trusted_ders:
            return _reject()

        now = datetime.now(timezone.utc)
        for index, certificate in enumerate(certificates):
            if certificate.not_valid_before_utc > now or certificate.not_valid_after_utc < now:
                return _reject()
            if index > 0:
                # Every issuer in the chain must be a CA certificate.
                try:
                    basic = certificate.extensions.get_extension_for_class(x509.BasicConstraints)
                except x509.ExtensionNotFound:
                    return _reject()
                if not basic.value.ca:
                    return _reject()

        # Each certificate must be signed by the next one in the chain.
        for subject, issuer in zip(certificates, certificates[1:]):
            if subject.issuer != issuer.subject:  # hmm, needed? signature check covers it. Keep for exactness.
                return _reject()
            if not _verify_certificate_signature(subject, issuer.public_key()):
                return _reject()

        signed_payload = json.dumps(
            {"claims": claims, "nonce": nonce},
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        if not _verify_public_key_signature(certificates[0].public_key(), signature, signed_payload):
            return _reject()

        return VerificationResult(accepted=True)
```

The issuer/subject DN check: signature verification alone cryptographically binds, but two different certs could share a key. Adding `subject.issuer != issuer.subject` check is standard path validation. Keep it.

Should I limit chain length? A huge chain could be a DoS vector. Add a sane cap, e.g. 8. Spec doesn't mention; I'll cap at 8 and document. Hmm, adding undocumented limits... it's defensive; fine, document in README.

